      const prefix = this.showCostTitle(this.singleCost) ? "价格：" : "";
      const suffix = this.isCostsAD ? `${this.costUnit}` : this.isFlipped ? "正物质" : "反物质";
      return `${prefix} ${format(this.singleCost)} ${suffix}`;
