  let calcBoosts;
  calcBoosts = cm.max(1).div(amount).log(multiplierPerDB);
  calcBoosts = calcBoosts.min(DC.E12).times(calcBoosts.div(DC.E12).max(1).pow(0.5)); // Add one cause (x-b)/i is off by one otherwise

  if (calcBoosts.floor().add(1).lte(CelestialDimBoost.purchasedBoosts)) return;
